#!/bin/sh
# Only for a DISPOSABLE project copy. Reverts two self-review fixes, not user data.
set -eu
if [ "$#" -ne 1 ]; then echo "Usage: ROLLBACK.sh /absolute/path/to/disposable-project-copy" >&2; exit 2; fi
if python -c 'import sys; sys.exit(sys.version_info < (3,11))' >/dev/null 2>&1; then
  PY=python
elif python3 -c 'import sys; sys.exit(sys.version_info < (3,11))' >/dev/null 2>&1; then
  PY=python3
else
  echo "Python 3.11+ required" >&2; exit 127
fi
"$PY" - "$1" <<'PY'
import base64,sys
from pathlib import Path
root=Path(sys.argv[1]).resolve()
if not (root/'minagent'/'runtime.py').is_file() or not (root/'minagent'/'store.py').is_file():
    raise SystemExit('Refusing: not a disposable minimal-agent copy')
files={'minagent/runtime.py': '', 'minagent/store.py': ''}
for name,data in files.items():
    (root/name).write_bytes(base64.b64decode(data))
print('Restored baseline runtime.py and store.py; no database or .env touched.')
PY
